content.query:
let file1 = BoxEvents
| where isnotempty(SourceFileName)
| summarize d_files = dcount(SourceFileName);
let file2 = BoxEvents
| where isnotempty(SourceItemName)
| summarize d_files = dcount(SourceItemName);
let files = union file1, file2;
files
| summarize sum(d_files)

